#!/usr/bin/env python3
"""csvq - tiny SQL-like filter/select/sort tool for CSV files.

Usage: csvq [--where COL=VALUE]... [--select COL,COL,...]
            [--sort COL [--numeric] [--desc]] FILE
"""
import csv
import sys

USAGE = ("usage: csvq [--where COL=VALUE]... [--select COL,COL,...] "
         "[--sort COL [--numeric] [--desc]] FILE")


class UsageError(Exception):
    pass


class UnknownColumn(Exception):
    def __init__(self, name):
        super().__init__(name)
        self.name = name


def parse_args(argv):
    wheres = []      # list of (col, value)
    select = None    # list of col names or None
    sort_col = None
    numeric = False
    desc = False
    files = []

    i = 0
    n = len(argv)
    while i < n:
        a = argv[i]
        if a == '--':
            files.extend(argv[i + 1:])
            break
        if a in ('-h', '--help'):
            print(USAGE)
            sys.exit(0)
        if a.startswith('--where='):
            wheres.append(a[len('--where='):])
        elif a == '--where':
            i += 1
            if i >= n:
                raise UsageError('--where requires an argument')
            wheres.append(argv[i])
        elif a.startswith('--select='):
            select = a[len('--select='):].split(',')
        elif a == '--select':
            i += 1
            if i >= n:
                raise UsageError('--select requires an argument')
            select = argv[i].split(',')
        elif a.startswith('--sort='):
            sort_col = a[len('--sort='):]
        elif a == '--sort':
            i += 1
            if i >= n:
                raise UsageError('--sort requires an argument')
            sort_col = argv[i]
        elif a == '--numeric':
            numeric = True
        elif a == '--desc':
            desc = True
        elif a.startswith('--') and a != '--':
            raise UsageError('unknown option: %s' % a)
        else:
            files.append(a)
        i += 1

    if len(files) != 1:
        raise UsageError('exactly one FILE argument is required')

    parsed_where = []
    for w in wheres:
        if '=' not in w:
            raise UsageError("--where expects COL=VALUE: %r" % w)
        col, val = w.split('=', 1)   # split at the first '='
        parsed_where.append((col, val))

    return parsed_where, select, sort_col, numeric, desc, files[0]


def is_number(s):
    try:
        float(s)
    except (ValueError, OverflowError):
        return False
    return True


def main(argv):
    try:
        wheres, select, sort_col, numeric, desc, path = parse_args(argv)
    except UsageError as e:
        print('csvq: %s' % e, file=sys.stderr)
        print(USAGE, file=sys.stderr)
        return 2

    try:
        f = open(path, 'r', newline='', encoding='utf-8-sig')
    except OSError as e:
        print('csvq: %s' % e, file=sys.stderr)
        return 2

    with f:
        rows = list(csv.reader(f))

    if not rows:
        print('csvq: %s: empty file (no header row)' % path, file=sys.stderr)
        return 2

    header = rows[0]
    data = rows[1:]

    # Resolve every referenced column; the first unknown one is fatal.
    def col_index(name):
        try:
            return header.index(name)
        except ValueError:
            raise UnknownColumn(name)

    try:
        where_idx = [(col_index(c), v) for c, v in wheres]
        if select is None:
            select_idx = list(range(len(header)))
            out_header = list(header)
        else:
            select_idx = [col_index(c) for c in select]
            out_header = list(select)
        sort_idx = col_index(sort_col) if sort_col is not None else None
    except UnknownColumn as e:
        print('csvq: unknown column: %s' % e.name, file=sys.stderr)
        return 2

    def cell(row, i):
        # tolerate ragged rows: missing trailing fields read as empty
        return row[i] if i < len(row) else ''

    kept = [r for r in data if all(cell(r, i) == v for i, v in where_idx)]

    if sort_idx is not None:
        if numeric:
            # non-numeric values (incl. empty) always go last, input order kept
            keyed = [(0, float(cell(r, sort_idx))) if is_number(cell(r, sort_idx))
                     else (1, 0.0) for r in kept]
            order = sorted(range(len(kept)),
                           key=lambda k: (keyed[k][0], -keyed[k][1]) if desc
                           else keyed[k])
        else:
            order = sorted(range(len(kept)),
                           key=lambda k: cell(kept[k], sort_idx),
                           reverse=desc)
        kept = [kept[k] for k in order]

    out = csv.writer(sys.stdout, lineterminator='\n')
    out.writerow(out_header)
    for r in kept:
        out.writerow([cell(r, i) for i in select_idx])

    try:
        sys.stdout.flush()
    except BrokenPipeError:
        return 0
    return 0


if __name__ == '__main__':
    sys.exit(main(sys.argv[1:]))
